import json, time, urllib.request, urllib.error, urllib.parse, datetime, sys
BASE='http://localhost:8080'
token=None

def get_token():
    req=urllib.request.Request(BASE+'/token', method='POST')
    with urllib.request.urlopen(req, timeout=30) as resp:
        return json.load(resp)['token']

def request(path, method='GET', auth=True):
    global token
    attempts=0
    while True:
        attempts += 1
        if auth and token is None:
            token=[REDACTED_SECRET]
        headers={}
        if auth:
            headers['Authorization']='Bearer '+token
        req=urllib.request.Request(BASE+path, headers=headers, method=method)
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                return json.load(resp)
        except urllib.error.HTTPError as e:
            if e.code == 401 and auth:
                token=None
                if attempts < 20:
                    continue
                raise
            if e.code == 429:
                retry=e.headers.get('Retry-After')
                if retry is None:
                    body=e.read().decode('utf8','replace')
                    raise RuntimeError(f'429 without Retry-After: {body}')
                delay=float(retry)
                print(f'rate limited; waiting {delay}s', file=sys.stderr, flush=True)
                time.sleep(delay)
                continue
            if e.code >= 500 and attempts < 10:
                time.sleep(min(attempts, 5))
                continue
            raise
        except (urllib.error.URLError, TimeoutError, ConnectionError) as e:
            if attempts >= 10:
                raise
            time.sleep(min(attempts, 5))

orders=[]
seen=set()
duplicates=0
page_path='/orders?page=1'
expected_total_pages=None
pages=0
while page_path:
    data=request(page_path)
    pages += 1
    if expected_total_pages is None:
        expected_total_pages=data.get('total_pages')
    elif data.get('total_pages') "'!= expected_total_pages:
        raise RuntimeError(f'"'total_pages changed: {expected_total_pages} -> {data.get(\"total_pages\")}')
    if data.get('page') "'!= pages:
        print(f'"'page response reports {data.get(\"page\")} while traversal index is {pages}', file=sys.stderr)
    for o in data['items']:
        if o['id'] in seen:
            duplicates += 1
        else:
            seen.add(o['id'])
            orders.append(o)
    page_path=data.get('next')
if expected_total_pages is not None and pages "'!= expected_total_pages:
    raise RuntimeError(f'"'Fetched {pages} pages; expected {expected_total_pages}')

customers={}
qualifying=[]
start=datetime.datetime(2025,3,1,tzinfo=datetime.timezone.utc)
end=datetime.datetime(2025,6,1,tzinfo=datetime.timezone.utc)
for o in orders:
    dt=datetime.datetime.fromisoformat(o['placed_at'].replace('Z','+00:00')).astimezone(datetime.timezone.utc)
    if o['status'] == 'shipped' and start <= dt < end:
        qualifying.append(o)

by_region={k:0 for k in ('north','south','east','west')}
for o in qualifying:
    cid=o['customer_id']
    if cid not in customers:
        customers[cid]=request('/customers/'+urllib.parse.quote(str(cid), safe=''))
    c=customers[cid]
    cents=o['amount_cents']*(100-c['discount_pct'])
    discounted=(cents+50)//100
    if c['region'] not in by_region:
        raise RuntimeError(f'Unexpected region {c[\"region\"]}')
    by_region[c['region']]+=discounted
result={'total_cents':sum(by_region.values()),'order_count':len(qualifying),'duplicates_skipped':duplicates,'by_region':by_region}
print(json.dumps({'pages':pages,'listed':sum(1 for _ in [])}, file=sys.stderr))
# report audit details without writing deliverable
print(json.dumps({'unique_listed_orders':len(orders),'duplicates_skipped':duplicates,'qualifying_orders':len(qualifying),'customer_records_fetched':len(customers),'result':result}, sort_keys=True))
